// Normalize only the ZIP timestamp fields generated by the pinned XLSX writer.
// Fixed DOS time/date: 1980-01-01 00:00:00. ZIP CRCs cover entry data, not these fields.
const FIXED_DOS_DATE = 0x0021;

/** Validate the writer's ordinary, single-disk, comment/extra-free ZIP before normalizing. */
export function normalizeAbkXlsxZip(input: Uint8Array): Uint8Array {
  const zip = Buffer.from(input);
  const eocd = zip.length - 22;
  const invalid = (): never => { throw new Error("Unexpected ABK XLSX ZIP layout"); };
  if (eocd < 0 || zip.readUInt32LE(eocd) !== 0x06054b50 ||
      zip.readUInt32LE(eocd + 4) !== 0 || zip.readUInt16LE(eocd + 20) !== 0) return invalid();
  const count = zip.readUInt16LE(eocd + 10);
  const central = zip.readUInt32LE(eocd + 16);
  if (count === 0 || count === 0xffff || zip.readUInt16LE(eocd + 8) !== count ||
      central + zip.readUInt32LE(eocd + 12) !== eocd || central + 46 * count > eocd) return invalid();

  let location = central;
  const ranges: { offset: number; dataEnd: number; directory: number; descriptor: boolean }[] = [];
  for (let i = 0; i < count; i++) {
    if (location + 46 > eocd || zip.readUInt32LE(location) !== 0x02014b50) return invalid();
    const flags = zip.readUInt16LE(location + 8);
    const method = zip.readUInt16LE(location + 10);
    const compressed = zip.readUInt32LE(location + 20);
    const uncompressed = zip.readUInt32LE(location + 24);
    const nameLength = zip.readUInt16LE(location + 28);
    const offset = zip.readUInt32LE(location + 42);
    const next = location + 46 + nameLength;
    if ((flags & ~0x080e) !== 0 || (method !== 0 && method !== 8) ||
        uncompressed === 0xffffffff || compressed === 0xffffffff ||
        nameLength === 0 || next > eocd || zip.readUInt16LE(location + 30) !== 0 ||
        zip.readUInt16LE(location + 32) !== 0 || zip.readUInt16LE(location + 34) !== 0 ||
        offset + 30 + nameLength > central || zip.readUInt32LE(offset) !== 0x04034b50 ||
        zip.readUInt16LE(offset + 6) !== flags || zip.readUInt16LE(offset + 8) !== method ||
        zip.readUInt16LE(offset + 26) !== nameLength || zip.readUInt16LE(offset + 28) !== 0 ||
        !zip.subarray(offset + 30, offset + 30 + nameLength).equals(zip.subarray(location + 46, next))) {
      return invalid();
    }
    const dataEnd = offset + 30 + nameLength + compressed;
    if (dataEnd > central) return invalid();
    const descriptor = (flags & 8) !== 0;
    if (!descriptor && (zip.readUInt32LE(offset + 14) !== zip.readUInt32LE(location + 16) ||
        zip.readUInt32LE(offset + 18) !== compressed || zip.readUInt32LE(offset + 22) !== uncompressed)) return invalid();
    ranges.push({ offset, dataEnd, directory: location, descriptor });
    location = next;
  }
  if (location !== eocd) return invalid();
  ranges.sort((a, b) => a.offset - b.offset);
  if (ranges[0]!.offset !== 0) return invalid();
  for (let i = 0; i < ranges.length; i++) {
    const r = ranges[i]!;
    const end = ranges[i + 1]?.offset ?? central;
    if (r.dataEnd > end) return invalid();
    if (!r.descriptor && end !== r.dataEnd) return invalid();
    if (r.descriptor) {
      const gap = end - r.dataEnd;
      if (gap !== 12 && gap !== 16) return invalid();
      if (gap === 16 && zip.readUInt32LE(r.dataEnd) !== 0x08074b50) return invalid();
      const descriptor = end - 12;
      for (let j = 0; j < 12; j += 4) {
        if (zip.readUInt32LE(descriptor + j) !== zip.readUInt32LE(r.directory + 16 + j)) return invalid();
      }
    }
    zip.writeUInt16LE(0, r.offset + 10);
    zip.writeUInt16LE(FIXED_DOS_DATE, r.offset + 12);
    zip.writeUInt16LE(0, r.directory + 12);
    zip.writeUInt16LE(FIXED_DOS_DATE, r.directory + 14);
  }
  return zip;
}
